        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters),
              data.count == ids.count * 2 * bytesPerEye else {
            preconditionFailure("Invalid generated approved-eye catalog")
        }
        return data
    }()

    public static func contains(_ id: String) -> Bool { indexByID[id] != nil }

    public static func bitmap(for id: String, side: Side) -> Data? {
        guard let index = indexByID[id] else { return nil }
        let start = (index * 2 + side.rawValue) * bytesPerEye
        return packed.subdata(in: start..<(start + bytesPerEye))
    }

    public static func recommendedScale(for id: String) -> (width: Double, height: Double)? {
        guard let index = indexByID[id] else { return nil }
        return (recommendedWidths[index], recommendedHeights[index])
    }

    public static func recommendedEyeSpacing(for id: String) -> Int? {
        guard let index = indexByID[id] else { return nil }
        return recommendedEyeSpacings[index]
    }

    public static func coverage(in bitmap: Data, x: Int, y: Int) -> UInt8 {
        guard bitmap.count == bytesPerEye,
              (0..<width).contains(x),
              (0..<height).contains(y) else { return 0 }
        let value = bitmap[y * rowBytes + x / 2]
        return x.isMultiple(of: 2) ? value >> 4 : value & 0x0F
    }

    public static func pixelIsSet(in bitmap: Data, x: Int, y: Int) -> Bool {
        coverage(in: bitmap, x: x, y: y) >= 8
    }
}
